package mz.bam.seeky.android;
import android.content.Context;
final class AppPalette {
 static final String[] NAMES={"Claro","Escuro","Jade","Oceano","Coral","Âmbar","Rosa","Grafite","Azul royal","Turquesa","Esmeralda","Laranja","Vinho","Lavanda","Céu","Noite"};
 final int bg,surface,ink,muted,accent,line,tint,heroStart,heroEnd,onAccent;final boolean light;
 AppPalette(String name){light=!name.equals("Escuro")&&!name.equals("Jade")&&!name.equals("Grafite")&&!name.equals("Noite");int a=name.equals("Azul royal")?0xff2553c7:name.equals("Turquesa")?0xff007f83:name.equals("Esmeralda")?0xff167347:name.equals("Laranja")?0xffb84a0e:name.equals("Vinho")?0xffa12550:name.equals("Lavanda")?0xff7352ae:name.equals("Céu")?0xff0875a4:name.equals("Noite")?0xffa8bcff:name.equals("Oceano")?0xff0369a1:name.equals("Coral")?0xffc24136:name.equals("Âmbar")?0xff956000:name.equals("Rosa")?0xffb52169:name.equals("Jade")?0xff66dab0:name.equals("Grafite")?0xffa2b8d3:name.equals("Escuro")?0xffb9a5ff:0xff7c13d9;accent=a;bg=light?ThemeColors.blend(0xffffffff,accent,.035f):name.equals("Jade")?0xff0c1c18:0xff10141d;surface=light?0xffffffff:name.equals("Jade")?0xff172d26:0xff1b2230;ink=light?0xff1c2536:0xffedf2fa;muted=light?0xff59677a:0xffaab8cc;line=light?0xffdce3ed:0xff303c4e;tint=ThemeColors.blend(surface,accent,light?.055f:.095f);onAccent=light?0xffffffff:0xff111821;heroStart=ThemeColors.hero(accent,light,bg);heroEnd=ThemeColors.blend(heroStart,0xff000000,.24f);}
 AppPalette(int requested,int background){bg=background|0xff000000;light=contrast(bg,0xff000000)>=contrast(bg,0xffffffff);surface=ThemeColors.blend(bg,light?0xffffffff:0xff141a24,.82f);ink=light?0xff000000:0xffffffff;int secondary=ThemeColors.blend(ink,surface,.30f);for(int i=0;i<30&&(contrast(secondary,bg)<4.5||contrast(secondary,surface)<4.5);i++)secondary=ThemeColors.blend(secondary,ink,.13f);muted=contrast(secondary,bg)>=4.5&&contrast(secondary,surface)>=4.5?secondary:ink;int candidate=requested|0xff000000;for(int i=0;i<30&&(contrast(candidate,bg)<4.5||contrast(candidate,surface)<4.5);i++)candidate=ThemeColors.blend(candidate,ink,.13f);if(contrast(candidate,bg)<4.5||contrast(candidate,surface)<4.5)candidate=ink;accent=candidate;line=ThemeColors.blend(surface,ink,.16f);tint=ThemeColors.blend(surface,accent,.08f);onAccent=contrast(accent,0xffffffff)>=4.5?0xffffffff:0xff000000;int hero=ThemeColors.hero(accent,light,bg);for(int i=0;i<30&&contrast(hero,0xffffffff)<4.5;i++)hero=ThemeColors.blend(hero,0xff000000,.12f);heroStart=hero;heroEnd=ThemeColors.blend(hero,0xff000000,.24f);}
 static double luminance(int c){double total=0;double[] weights={.2126,.7152,.0722};for(int i=0;i<3;i++){double channel=((c>>(16-i*8))&255)/255.;total+=weights[i]*(channel<=.04045?channel/12.92:Math.pow((channel+.055)/1.055,2.4));}return total;}
 static double contrast(int a,int b){double x=luminance(a),y=luminance(b);return (Math.max(x,y)+.05)/(Math.min(x,y)+.05);}
 static AppPalette of(Context c){android.content.SharedPreferences p=c.getSharedPreferences("seeky",0);String name=p.getString("theme","Claro");return name.equals("Personalizado")?new AppPalette(p.getInt("theme_custom_accent",0xff7c13d9),p.getInt("theme_custom_background",0xfffaf8ff)):new AppPalette(name);}
}
